output = {}

for store_id, records in raw_data.items():
    coords = []
    for r in records:
        lat = r.get('latitude')
        lon = r.get('longitude')
        if lat is not None and lon is not None:
            coords.append({"lat": lat, "lon": lon})
    output[store_id] = coords

out_path = '/app/conversations/69f0c699777455158d804588/patient_coords.json'
with open(out_path, 'w') as f:
    json.dump(output, f, indent=2)

print("File written successfully. Count summary:")
